package com.ofaro.participaciones;

import android.app.Activity;
import android.app.AlertDialog;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.os.Bundle;
import android.text.InputType;
import android.view.Gravity;
import android.view.View;
import android.view.ViewGroup;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.ScrollView;
import android.widget.TextView;
import android.widget.Toast;

import org.json.JSONArray;
import org.json.JSONObject;

import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

/** Gestión web nativa. La interfaz nunca espera a la red para dibujarse. */
public class WebManagementActivity extends Activity {
    private final ExecutorService io=Executors.newSingleThreadExecutor();
    private AppCore core;private LinearLayout page;private TextView subtitle;
    private String currentSection="",currentTitle="";private JSONObject currentMeta;

    @Override protected void onCreate(Bundle b){super.onCreate(b);core=new AppCore(this);setContentView(buildRoot());showHome();}
    @Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}

    private View buildRoot(){LinearLayout root=col();root.setBackgroundColor(Color.rgb(246,246,246));LinearLayout header=col();header.setPadding(dp(20),dp(18),dp(20),dp(16));header.setBackgroundColor(Color.rgb(17,17,17));header.addView(text("MESÓN O FARO",23,Color.WHITE,true));subtitle=text("Gestión de la web",14,Color.rgb(210,210,210),false);header.addView(subtitle);root.addView(header);ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);page=col();page.setPadding(dp(18),dp(20),dp(18),dp(30));scroll.addView(page);root.addView(scroll,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,0,1));return root;}

    private void showHome(){clear("Gestión de la web");addBackTo("Contenido web",this::finish);page.addView(paragraph("Edita el contenido que alimenta la web pública. La APK muestra primero la última copia guardada y sincroniza después."));TextView status=statusCard("");page.addView(status);LinearLayout list=col();page.addView(list,marginTopWrap(dp(10)));Button refresh=secondaryButton("ACTUALIZAR");refresh.setOnClickListener(v->refreshSections(status,list,refresh));page.addView(refresh,marginTop(dp(10)));
        JSONArray cached=core.cachedArray("web_sections");paintSections(list,cached);status.setText(cacheStatus("Apartados",cached,"web_sections"));refreshSections(status,list,refresh);}

    private void refreshSections(TextView status,LinearLayout list,Button button){if(!canRefresh(status))return;button.setEnabled(false);status.setText("Apartados · actualizando en segundo plano…");io.execute(()->{try{JSONObject res=core.post(core.action("webSections"));JSONArray items=res.optJSONArray("items");if(items==null)items=new JSONArray();core.saveArray("web_sections",items);JSONArray out=items;runOnUiThread(()->{button.setEnabled(true);paintSections(list,out);status.setText(out.length()+" apartados · actualizado ahora");});}catch(Exception e){runOnUiThread(()->{button.setEnabled(true);JSONArray c=core.cachedArray("web_sections");status.setText(c.length()>0?"Apartados · sin conexión · mostrando copia guardada":"No se pudo cargar · "+cleanError(e));});}});}
    private void paintSections(LinearLayout list,JSONArray items){list.removeAllViews();if(items.length()==0){list.addView(emptyText("Todavía no hay apartados guardados en este dispositivo."));return;}for(int i=0;i<items.length();i++){JSONObject s=items.optJSONObject(i);if(s==null)continue;String key=s.optString("key","");String title=s.optString("title",key);Button b=bigButton(title,s.optString("description","Editar datos de la web"));b.setOnClickListener(v->showSection(key,title));list.addView(b,marginBottomWrap(dp(10)));}}

    private void showSection(String key,String title){currentSection=key;currentTitle=title;clear(title);addBackTo(title,this::showHome);TextView status=statusCard("");page.addView(status);LinearLayout controls=col();page.addView(controls,marginTopWrap(dp(8)));LinearLayout list=col();page.addView(list,marginTopWrap(dp(8)));Button refresh=secondaryButton("ACTUALIZAR");refresh.setOnClickListener(v->refreshSection(key,status,controls,list,refresh));page.addView(refresh,marginTop(dp(10)));
        JSONObject cached=cachedObject(sectionCacheName(key));if(cached!=null){paintSection(cached,true,status,controls,list);}else status.setText("Sin copia local · actualizando…");refreshSection(key,status,controls,list,refresh);}

    private void refreshSection(String key,TextView status,LinearLayout controls,LinearLayout list,Button button){if(!canRefresh(status))return;button.setEnabled(false);if(currentMeta==null)status.setText("Actualizando sección…");io.execute(()->{try{JSONObject res=core.post(core.action("webSectionRows").put("section",key));saveObject(sectionCacheName(key),res);runOnUiThread(()->{button.setEnabled(true);paintSection(res,false,status,controls,list);});}catch(Exception e){runOnUiThread(()->{button.setEnabled(true);status.setText(currentMeta!=null?"Sin conexión · mostrando copia guardada":"No se pudo abrir · "+cleanError(e));});}});}

    private void paintSection(JSONObject res,boolean cached,TextView status,LinearLayout controls,LinearLayout list){currentMeta=res;JSONArray rows=res.optJSONArray("rows");if(rows==null)rows=new JSONArray();boolean allowAdd=res.optBoolean("allowAdd",false);status.setText((cached?"Copia guardada · ":"Actualizado · ")+rows.length()+" registros");controls.removeAllViews();list.removeAllViews();if(allowAdd){Button add=primaryButton("+ AÑADIR");add.setOnClickListener(v->editRow(new JSONObject(),true));controls.addView(add);}if(rows.length()==0){list.addView(emptyText("No hay registros."));return;}for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null)addRowCard(list,row);}}

    private void addRowCard(LinearLayout list,JSONObject row){LinearLayout card=cardBox();JSONArray fields=currentMeta==null?null:currentMeta.optJSONArray("fields");String head="Registro",secondary="";if(fields!=null)for(int i=0;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);if(f==null||f.optBoolean("hidden",false))continue;String key=f.optString("key","");String val=row.optString(key,"").trim();if(val.isEmpty())continue;if("Registro".equals(head)&&!f.optBoolean("readOnly",false))head=val;else if(secondary.isEmpty())secondary=f.optString("label",key)+": "+val;}card.addView(text(head,18,Color.rgb(20,20,20),true));if(!secondary.isEmpty()){TextView s=text(secondary,13,Color.DKGRAY,false);s.setPadding(0,dp(5),0,dp(10));card.addView(s);}Button edit=primaryButton("EDITAR");edit.setOnClickListener(v->editRow(row,false));card.addView(edit);list.addView(card,marginBottomWrap(dp(10)));}

    private void editRow(JSONObject row,boolean isNew){clear("Editar · "+currentTitle);addBackTo("Editar",()->showSection(currentSection,currentTitle));JSONArray fields=currentMeta==null?null:currentMeta.optJSONArray("fields");if(fields==null){alert("Error","No se recibió la definición de campos.");return;}LinkedHashMap<String,EditText> editors=new LinkedHashMap<>();for(int i=0;i<fields.length();i++){JSONObject f=fields.optJSONObject(i);if(f==null||f.optBoolean("hidden",false))continue;String key=f.optString("key","");String label=f.optString("label",key);String value=row.optString(key,"");boolean readOnly=f.optBoolean("readOnly",false);String type=f.optString("type","text");boolean multi=f.optBoolean("multiline",false);TextView l=text(label,14,Color.DKGRAY,true);l.setPadding(dp(2),dp(12),dp(2),dp(6));page.addView(l);if(readOnly&&!isNew){TextView ro=text(value.isEmpty()?"—":value,15,Color.rgb(35,35,35),false);ro.setPadding(dp(12),dp(12),dp(12),dp(12));ro.setBackground(roundRect(Color.rgb(238,238,238),10,Color.rgb(210,210,210),1));page.addView(ro);continue;}EditText e=input(value);if("number".equals(type))e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);else e.setInputType(InputType.TYPE_CLASS_TEXT);if(multi){e.setSingleLine(false);e.setMinLines(4);e.setGravity(Gravity.TOP);e.setPadding(dp(14),dp(12),dp(14),dp(12));page.addView(e,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT));}else{e.setSingleLine(true);page.addView(e,new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,dp(54)));}editors.put(key,e);}
        Button save=primaryButton("GUARDAR CAMBIOS");page.addView(save,marginTop(dp(18)));save.setOnClickListener(v->{JSONObject values=new JSONObject();try{for(Map.Entry<String,EditText> en:editors.entrySet())values.put(en.getKey(),en.getValue().getText().toString().trim());JSONArray fs=currentMeta.optJSONArray("fields");if(fs!=null)for(int i=0;i<fs.length();i++){JSONObject f=fs.optJSONObject(i);if(f!=null&&f.optBoolean("readOnly",false)){String k=f.optString("key","");if(row.has(k))values.put(k,row.opt(k));}}}catch(Exception ignored){}if(!core.configured()||!core.internetAvailable()){alert("Sin conexión","Para guardar cambios en la web necesitas conexión al servidor. Tus datos actuales siguen intactos.");return;}save.setEnabled(false);io.execute(()->{try{core.post(core.action("webSectionSave").put("section",currentSection).put("values",values));runOnUiThread(()->{toast("Cambios guardados");invalidateSectionCache(currentSection);showSection(currentSection,currentTitle);});}catch(Exception e){runOnUiThread(()->{save.setEnabled(true);alert("No se pudo guardar",cleanError(e));});}});});
        if(!isNew&&currentMeta.optBoolean("allowDelete",false)){Button del=secondaryButton("ELIMINAR REGISTRO");page.addView(del,marginTop(dp(10)));del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Eliminar").setMessage("¿Eliminar este registro? El cambio afectará a la web.").setNegativeButton("Cancelar",null).setPositiveButton("ELIMINAR",(d,w)->deleteRow(row)).show());}}

    private void deleteRow(JSONObject row){String idKey=currentMeta.optString("idKey","id"),id=row.optString(idKey,"");if(id.isEmpty()){alert("Error","No se encuentra el identificador del registro.");return;}if(!core.configured()||!core.internetAvailable()){alert("Sin conexión","No se puede eliminar sin conexión al servidor.");return;}io.execute(()->{try{core.post(core.action("webSectionDelete").put("section",currentSection).put("id",id));runOnUiThread(()->{toast("Registro eliminado");invalidateSectionCache(currentSection);showSection(currentSection,currentTitle);});}catch(Exception e){runOnUiThread(()->alert("No se pudo eliminar",cleanError(e)));}});}

    private boolean canRefresh(TextView status){if(!core.configured()){status.setText("Servidor sin configurar · mostrando datos locales");return false;}if(!core.internetAvailable()){status.setText("Sin Internet · mostrando datos locales");return false;}return true;}
    private String sectionCacheName(String key){return"web_section_"+key.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9_-]","_");}
    private void saveObject(String name,JSONObject value){core.prefs().edit().putString("cache_"+name,value==null?"{}":value.toString()).putLong("cache_"+name+"_at",System.currentTimeMillis()).apply();}
    private JSONObject cachedObject(String name){try{String raw=core.prefs().getString("cache_"+name,"");return raw==null||raw.trim().isEmpty()?null:new JSONObject(raw);}catch(Exception e){return null;}}
    private void invalidateSectionCache(String key){String name=sectionCacheName(key);core.prefs().edit().remove("cache_"+name).remove("cache_"+name+"_at").apply();currentMeta=null;}
    private String cacheStatus(String label,JSONArray a,String key){if(a.length()==0)return label+" · sin datos locales · actualizando…";long age=core.cacheAgeMs(key),m=age==Long.MAX_VALUE?0:age/60000;return label+" · "+a.length()+" guardados · "+(m<1?"ahora":m+" min");}

    private void clear(String s){page.removeAllViews();subtitle.setText(s);}private void addBackTo(String title,Runnable action){LinearLayout bar=row();bar.setGravity(Gravity.CENTER_VERTICAL);Button back=secondaryButton("‹ ATRÁS");back.setOnClickListener(v->action.run());bar.addView(back,new LinearLayout.LayoutParams(dp(105),dp(48)));TextView t=text(title,21,Color.rgb(20,20,20),true);t.setGravity(Gravity.CENTER_VERTICAL);t.setPadding(dp(12),0,0,0);bar.addView(t,new LinearLayout.LayoutParams(0,dp(48),1));page.addView(bar);page.addView(space(dp(12)));}
    private Button bigButton(String title,String sub){Button b=primaryButton(title+"\n"+sub);b.setGravity(Gravity.LEFT|Gravity.CENTER_VERTICAL);b.setPadding(dp(18),0,dp(18),0);b.setMinHeight(dp(76));return b;}private Button primaryButton(String label){Button b=new Button(this);b.setText(label);b.setTextSize(14);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setTextColor(Color.WHITE);b.setAllCaps(false);b.setBackground(roundRect(Color.rgb(17,17,17),12,Color.TRANSPARENT,0));b.setMinHeight(dp(54));return b;}private Button secondaryButton(String label){Button b=new Button(this);b.setText(label);b.setTextSize(13);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setTextColor(Color.rgb(20,20,20));b.setAllCaps(false);b.setBackground(roundRect(Color.WHITE,12,Color.rgb(190,190,190),1));b.setMinHeight(dp(52));return b;}private LinearLayout cardBox(){LinearLayout c=col();c.setPadding(dp(16),dp(15),dp(16),dp(15));c.setBackground(roundRect(Color.WHITE,14,Color.rgb(225,225,225),1));return c;}private TextView paragraph(String s){TextView t=text(s,15,Color.DKGRAY,false);t.setLineSpacing(0,1.15f);t.setPadding(0,0,0,dp(14));return t;}private TextView statusCard(String s){TextView t=text(s,13,Color.DKGRAY,false);t.setPadding(dp(12),dp(10),dp(12),dp(10));t.setBackground(roundRect(Color.WHITE,11,Color.rgb(214,214,214),1));return t;}private TextView emptyText(String s){TextView t=text(s,15,Color.DKGRAY,false);t.setPadding(dp(10),dp(14),dp(10),dp(14));return t;}private TextView text(String s,int sp,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}private EditText input(String value){EditText e=new EditText(this);e.setText(value);e.setTextSize(16);e.setTextColor(Color.rgb(20,20,20));e.setHintTextColor(Color.GRAY);e.setPadding(dp(14),0,dp(14),0);e.setBackground(roundRect(Color.WHITE,12,Color.rgb(205,205,205),1));return e;}private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);return l;}private View space(int h){View v=new View(this);v.setLayoutParams(new LinearLayout.LayoutParams(1,h));return v;}private GradientDrawable roundRect(int fill,int radius,int stroke,int sw){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(sw>0)d.setStroke(dp(sw),stroke);return d;}private LinearLayout.LayoutParams marginTop(int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.topMargin=top;return p;}private LinearLayout.LayoutParams marginTopWrap(int top){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.topMargin=top;return p;}private LinearLayout.LayoutParams marginBottomWrap(int bottom){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);p.bottomMargin=bottom;return p;}private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private String cleanError(Throwable t){String m=t==null?"Error desconocido":t.getMessage();if(m==null||m.trim().isEmpty())m=String.valueOf(t);return m.length()>420?m.substring(0,420):m;}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}private void alert(String t,String m){if(!isFinishing())new AlertDialog.Builder(this).setTitle(t).setMessage(m).setPositiveButton("Aceptar",null).show();}
}
